LOGO_PNG_B64 = ""

FAVICON_ICO_B64 = ""

def get_png_bytes() -> bytes:
    return base64.b64decode(LOGO_PNG_B64)

def get_ico_bytes() -> bytes:
    return base64.b64decode(FAVICON_ICO_B64)

def get_svg_bytes() -> bytes:
    return LOGO_SVG.encode("utf-8")
